(() => {
 const el=id=>document.getElementById(id),names={map:'地圖與碰撞',object:'互動物件',visual:'場景美術與圖塊',decor:'單一美術物件',art:'所有 PNG 素材',catalog:'場所完整目錄',item:'單一品項',clothing:'服裝配方',actor:'人物公開設定',npc:'一般 NPC 腳本',events:'公共活動',rules:'底層規則',service:'AI 與服務',tool:'自訂 AI 工具',theme:'介面配色'};let catalog=null,proposal=null,definition=null;
 const report=(text,error=false)=>{el('components-status').textContent=text;el('components-status').classList.toggle('error',error);};
 async function api(operation,params={}){const r=await fetch('/api/components',operation?{method:'POST',headers:{'Content-Type':'application/json','X-Play-Token':token},body:JSON.stringify({operation,params})}:{headers:{'X-Play-Token':token}});const d=await r.json();if(!r.ok)throw Error(d.message||'部件操作無法完成');return d;}
 function clear(){proposal=null;el('components-apply').disabled=true;el('components-preview-text').textContent='修改後需重新預覽。';}
 function show(p){proposal=p;el('components-apply').disabled=false;el('components-preview-text').textContent=p.changes.map(c=>`${c.target}\n`+c.diff.map(d=>`${d.field}: ${d.before} → ${d.after}`).join('\n')).join('\n\n')+'\n\n'+p.effects.join('\n');report('驗證通過，尚未套用。');}
 function option(s,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;s.append(o);}
 async function read(){clear();const target=el('components-target').value;const d=await api('get',{target});if(el('components-target').value!==target)return;definition=d;el('components-json').value=JSON.stringify(d.value,null,2);el('components-info').textContent=`${d.target} · 部件版本 ${d.revision}`;el('components-upload').disabled=!d.target.startsWith('art:');report('已讀取部件；原記憶與物品不包含在這份定義。');}
 function targets(){const s=el('components-target'),old=s.value,q=el('components-search').value.trim().toLowerCase();s.replaceChildren();const rows=catalog.targets.filter(t=>t.kind===el('components-kind').value&&(t.id+' '+(t.label||'')).toLowerCase().includes(q));if(!rows.length&&el('components-kind').value==='tool')rows.push({id:'tool:custom',replaced:false});for(const t of rows.slice(0,200))option(s,t.id,(t.label&&t.label!==t.id?t.label+' · ':'')+t.id+(t.replaced?' · 已替換':''));if([...s.options].some(o=>o.value===old))s.value=old;el('components-info').textContent=`符合 ${rows.length} 個，最多列出 200 個；可輸入場景或物件 ID 縮小範圍。`;clear();if(s.value)read().catch(e=>report(e.message,true));}
 function history(){const box=el('components-history');box.replaceChildren();for(const h of [...catalog.history].reverse()){const p=document.createElement('p');p.textContent=h.instruction+' · '+h.targets.join(', ');const b=document.createElement('button');b.textContent='準備還原';b.onclick=()=>api('rollback',{history:h.id}).then(show).catch(e=>report(e.message,true));p.append(b);box.append(p);}}
 async function refresh(){catalog=await api();history();}
 el('components-open').onclick=async()=>{if(!state)return;game.keys.clear();el('components-modal').showModal();try{await refresh();const s=el('components-kind');if(!s.options.length)for(const [id,label] of Object.entries(names))option(s,id,label);targets();}catch(e){report(e.message,true);}};
 el('components-close').onclick=()=>el('components-modal').close();el('components-modal').addEventListener('close',()=>game.keys.clear());el('components-kind').onchange=targets;el('components-search').oninput=targets;el('components-target').onchange=()=>read().catch(e=>report(e.message,true));el('components-read').onclick=()=>read().catch(e=>report(e.message,true));el('components-json').oninput=clear;el('components-instruction').oninput=clear;
 el('components-plan').onclick=async()=>{try{show(await api('plan',{instruction:el('components-instruction').value,targets:[el('components-target').value]}));}catch(e){clear();report(e.message,true);}};
 el('components-preview').onclick=async()=>{try{const value=JSON.parse(el('components-json').value);if(!value.changes&&definition?.target!==el('components-target').value)throw Error('請先選擇並讀取要替換的部件');const p=value.changes?value:{instruction:el('components-instruction').value||'替換 '+definition.target,revision:catalog.revision,changes:[{target:definition.target,value}]};show(await api('prepare',p));}catch(e){clear();report(e.message,true);}};
 el('components-upload').onclick=async()=>{try{const file=el('components-png').files[0];if(!file||file.size>3*1024*1024)throw Error('請選擇 3 MB 以內的 PNG');const bytes=new Uint8Array(await file.arrayBuffer());let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));show(await api('prepare',{instruction:el('components-instruction').value||'替換圖片 '+definition.target,changes:[{target:definition.target,png:btoa(str)}]}));}catch(e){clear();report(e.message,true);}};
 el('components-apply').onclick=async()=>{if(!proposal)return;el('components-apply').disabled=true;try{const d=await api('apply',{proposal:proposal.id});proposal=null;report(d.notice);await refresh();await send('pulse',{},true);}catch(e){clear();report(e.message,true);}};
 el('components-export').onclick=async()=>{try{const d=await api('export',{targets:[el('components-target').value]});el('components-json').value=JSON.stringify(d,null,2);el('components-json').closest('details').open=true;report('部件包已顯示，可複製給替換 AI 或保存；圖片包含 PNG。');clear();}catch(e){report(e.message,true);}};
})();

